func (o *ExtractionJob) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("extractionJob cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.ExtractionJobs = ExtractionJobSlice{o}
		}
		return nil
	case "SourceDocument":
		rel, ok := retrieved.(*SourceDocument)
		if !ok {
			return fmt.Errorf("extractionJob cannot load %T as %q", retrieved, name)
		}

		o.R.SourceDocument = rel
		o.R.Loaded.SourceDocument = true

		if rel != nil {
			rel.R.ExtractionJobs = ExtractionJobSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("extractionJob has no relationship %q", name)
	}
}

